css:
.uic-title-pattern {
  --reset-time: 10s;
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 22rem;
  background-color: #080000;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  font-family: "Garamond", "Times New Roman", Times, serif;
  user-select: none;
  cursor: crosshair;
  box-sizing: border-box;
}

.uic-title-pattern .bg-glow,
.uic-title-pattern .bg-noise,
.uic-title-pattern .dust-layer,
.uic-title-pattern .doodle-layer,
.uic-title-pattern .doodle,
.uic-title-pattern .title-stage,
.uic-title-pattern .neon-line,
.uic-title-pattern .neon-line-inner,
.uic-title-pattern .main-title,
.uic-title-pattern .sub-title,
.uic-title-pattern .letter,
.uic-title-pattern .caption {
  box-sizing: border-box;
}

.uic-title-pattern .bg-glow {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 32rem;
  height: 32rem;
  background: radial-gradient(
    circle,
    rgba(180, 0, 0, 0.18) 0%,
    transparent 62%
  );
  transform: translate(-50%, -50%);
  animation: glowBreathing 6s ease-in-out infinite alternate;
  pointer-events: none;
  z-index: 1;
}

.uic-title-pattern .bg-noise {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 0, 0, 0.1) 1px, transparent 1px),
    radial-gradient(rgba(255, 0, 0, 0.05) 1px, transparent 1px);
  background-size:
    20px 20px,
    15px 15px;
  background-position:
    0 0,
    7.5px 7.5px;
  opacity: 0.3;
  z-index: 2;
  pointer-events: none;
  animation: noiseJitter 0.4s infinite;
}

.uic-title-pattern::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, transparent 40%, #000 100%);
  pointer-events: none;
  z-index: 20;
}

.uic-title-pattern .dust-layer {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.uic-title-pattern .dust-layer::before {
  content: "";
  position: absolute;
  width: 2px;
  height: 2px;
  background: transparent;
  box-shadow:
    3rem 4rem 1px rgba(255, 0, 0, 0.6),
    9rem 16rem 1px rgba(255, 0, 0, 0.4),
    18rem 7rem 1px rgba(255, 0, 0, 0.8),
    25rem 14rem 1px rgba(255, 0, 0, 0.5);
  animation: dustDrift 20s linear infinite;
}

.uic-title-pattern .title-stage {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: scale(0.78);
  transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.uic-title-pattern:hover .title-stage {
  transform: scale(0.82);
}

.uic-title-pattern .main-title,
.uic-title-pattern .sub-title {
  display: flex;
  justify-content: center;
  align-items: baseline;
  margin: 0;
  padding: 0;
  text-transform: uppercase;
  color: transparent;
  line-height: 0.9;
}

.uic-title-pattern .main-title {
  font-size: clamp(2.8rem, 5.5rem, 6.5rem);
  letter-spacing: -0.05em;
  margin-bottom: 0.1em;
}

.uic-title-pattern .sub-title {
  font-size: clamp(1.3rem, 2.8rem, 3.2rem);
  letter-spacing: 0.2em;
  margin-bottom: 0.5em;
}

.uic-title-pattern .main-title .letter:first-child,
.uic-title-pattern .main-title .letter:last-child {
  font-size: 1.25em;
}

.uic-title-pattern .letter {
  position: relative;
  display: inline-block;
  opacity: 0;
  filter: blur(12px);
  transform: translate(var(--x), var(--y)) rotate(var(--r)) scale(1.5);
  -webkit-text-stroke: 2px #f00;
  text-shadow:
    0 0 5px rgba(255, 0, 0, 0.8),
    0 0 15px rgba(255, 0, 0, 0.6),
    0 0 30px rgba(200, 0, 0, 0.4);
  animation:
    letterIntro var(--reset-time) cubic-bezier(0.2, 0.8, 0.2, 1) infinite,
    neonFlicker var(--reset-time) linear infinite;
  animation-delay: var(--d), 0s;
}

.uic-title-pattern .letter::before,
.uic-title-pattern .letter::after {
  content: attr(data-char);
  position: absolute;
  top: 0;
  left: 0;
  color: transparent;
  pointer-events: none;
}

.uic-title-pattern .letter::before {
  -webkit-text-stroke: 1px rgba(255, 50, 50, 0.7);
  transform: translate(2px, -2px) rotate(-1.5deg);
  z-index: -1;
  animation: sketchJitter 0.18s infinite alternate;
}

.uic-title-pattern .letter::after {
  -webkit-text-stroke: 1px rgba(200, 0, 0, 0.5);
  transform: translate(-2px, 1px) rotate(1.5deg);
  z-index: -2;
  animation: sketchJitter2 0.2s infinite alternate;
}

.uic-title-pattern .neon-line {
  position: relative;
  width: 0%;
  height: 2px;
  background: transparent;
  margin: 0.5em 0;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: lineReveal var(--reset-time) cubic-bezier(0.8, 0, 0.2, 1) infinite;
}

.uic-title-pattern .neon-line.top-line {
  margin-bottom: 0.8em;
}

.uic-title-pattern .neon-line.bottom-line {
  margin-top: 0.5em;
}

.uic-title-pattern .neon-line-inner {
  width: 100%;
  height: 100%;
  border-top: 1px solid #f00;
  border-bottom: 1px solid #f00;
  box-shadow:
    0 0 5px #f00,
    0 0 10px #f00,
    0 0 20px #a00,
    inset 0 0 2px #f00;
}

.uic-title-pattern .neon-line-inner::before {
  content: "";
  position: absolute;
  inset: -1px;
  border: 1px dashed rgba(255, 0, 0, 0.5);
  transform: rotate(0.2deg);
  animation: doodleJitter 0.2s infinite alternate;
}

.uic-title-pattern .caption {
  font-family: sans-serif;
  font-size: 0.6rem;
  color: #ff3333;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  margin-top: 2em;
  opacity: 0;
  text-shadow: 0 0 5px #f00;
  animation: captionFade var(--reset-time) infinite;
}

.uic-title-pattern .doodle-layer {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
}

.uic-title-pattern .doodle {
  position: absolute;
  opacity: 0;
  animation: doodleFadeBlink 5s infinite;
}

.uic-title-pattern .doodle.spark {
  width: 12px;
  height: 12px;
}

.uic-title-pattern .doodle.spark::before,
.uic-title-pattern .doodle.spark::after {
  content: "";
  position: absolute;
  background: #f00;
  box-shadow: 0 0 8px #f00;
  border-radius: 50%;
}

.uic-title-pattern .doodle.spark::before {
  width: 100%;
  height: 2px;
  top: 5px;
  left: 0;
}

.uic-title-pattern .doodle.spark::after {
  width: 2px;
  height: 100%;
  top: 0;
  left: 5px;
}

.uic-title-pattern .doodle.scratch {
  width: 20px;
  height: 2px;
  background: transparent;
  border-top: 2px solid #f00;
  border-bottom: 1px solid #a00;
  transform: rotate(-35deg);
  box-shadow: 0 0 5px #f00;
}

.uic-title-pattern .doodle.dot {
  width: 4px;
  height: 4px;
  background: #f00;
  border-radius: 50%;
  box-shadow: 0 0 10px #f00;
}

.uic-title-pattern .d1 {
  animation-delay: 3s;
}

.uic-title-pattern .d2 {
  animation-delay: 4.2s;
}

.uic-title-pattern .d3 {
  animation-delay: 3.5s;
}

.uic-title-pattern .d4 {
  animation-delay: 4.8s;
}

.uic-title-pattern .d5 {
  animation-delay: 3.9s;
}

.uic-title-pattern .d6 {
  animation-delay: 5.1s;
}

.uic-title-pattern:hover .doodle {
  animation-duration: 2s;
  box-shadow:
    0 0 15px #fff,
    0 0 30px #f00;
}

.uic-title-pattern:hover .main-title .letter {
  text-shadow:
    0 0 10px rgba(255, 100, 100, 0.9),
    0 0 20px rgba(255, 0, 0, 0.8),
    0 0 40px rgba(255, 0, 0, 0.6);
}

@keyframes letterIntro {
  0% {
    opacity: 0;
    filter: blur(12px);
    transform: translate(var(--x), var(--y)) rotate(var(--r)) scale(1.5);
  }

  30%,
  68% {
    opacity: 1;
    filter: blur(0);
    transform: translate(0, 0) rotate(0deg) scale(1);
  }

  92%,
  100% {
    opacity: 0;
    filter: blur(12px);
    transform: translate(var(--x), var(--y)) rotate(var(--r)) scale(1.5);
  }
}

@keyframes lineReveal {
  0%,
  16% {
    width: 0%;
    opacity: 0;
  }

  36%,
  68% {
    width: 110%;
    opacity: 1;
  }

  84%,
  100% {
    width: 0%;
    opacity: 0;
  }
}

@keyframes captionFade {
  0%,
  36% {
    opacity: 0;
  }

  48%,
  68% {
    opacity: 0.5;
  }

  84%,
  100% {
    opacity: 0;
  }
}

@keyframes glowBreathing {
  0% {
    transform: translate(-50%, -50%) scale(1);
    opacity: 0.7;
  }

  100% {
    transform: translate(-50%, -50%) scale(1.1);
    opacity: 1;
  }
}

@keyframes neonFlicker {
  0%,
  30%,
  62%,
  100% {
    opacity: 1;
  }

  20%,
  64% {
    opacity: 0.35;
  }

  92%,
  100% {
    opacity: 0;
  }
}

@keyframes doodleJitter {
  0% {
    transform: translate(0, 0) rotate(0deg);
  }

  50% {
    transform: translate(1px, -1px) rotate(0.3deg);
  }

  100% {
    transform: translate(-1px, 1px) rotate(-0.3deg);
  }
}

@keyframes sketchJitter {
  0% {
    transform: translate(2px, -2px) rotate(-1.5deg);
  }

  100% {
    transform: translate(3px, -1px) rotate(-1deg);
  }
}

@keyframes sketchJitter2 {
  0% {
    transform: translate(-2px, 1px) rotate(1.5deg);
  }

  100% {
    transform: translate(-3px, 2px) rotate(1deg);
  }
}

@keyframes noiseJitter {
  0% {
    background-position:
      0 0,
      7.5px 7.5px;
  }

  50% {
    background-position:
      2px -2px,
      5.5px 9.5px;
  }

  100% {
    background-position:
      -2px 2px,
      9.5px 5.5px;
  }
}

@keyframes dustDrift {
  0% {
    transform: translateY(0) translateX(0);
  }

  100% {
    transform: translateY(-12rem) translateX(5rem);
  }
}

@keyframes doodleFadeBlink {
  0%,
  10%,
  100% {
    opacity: 0;
    transform: scale(0.5);
  }

  5% {
    opacity: 1;
    transform: scale(1.2);
  }
}

@media (max-width: 600px) {
  .uic-title-pattern {
    min-height: 18rem;
  }

  .uic-title-pattern .title-stage {
    transform: scale(0.58);
  }

  .uic-title-pattern:hover .title-stage {
    transform: scale(0.62);
  }

  .uic-title-pattern .dust-layer::before {
    display: none;
  }
}
/* FULL HEIGHT FIT INSIDE CARD - NO vw / vh UNITS */
.card-content,
.clickable-wrapper,
.card__button-container,
.preview-container,
#container {
  width: 100%;
  height: 100%;
  min-height: 250px;
  overflow: hidden;
  position: relative;
}

#container .uic-title-pattern {
  width: 100%;
  height: 100%;
  min-height: 100%;
  max-height: none;
  overflow: hidden;
}

/* Fit the title inside full height */
#container .uic-title-pattern .title-stage {
  transform: scale(0.58);
  transform-origin: center;
}

#container .uic-title-pattern:hover .title-stage {
  transform: scale(0.62);
}

/* Glow fit without vw/vh */
#container .uic-title-pattern .bg-glow {
  width: 28rem;
  height: 28rem;
}

/* No vw allowed, so use rem only */
#container .uic-title-pattern .main-title {
  font-size: clamp(2rem, 4.8rem, 5.8rem);
}

#container .uic-title-pattern .sub-title {
  font-size: clamp(1rem, 2.4rem, 2.8rem);
}

/* Keep caption inside */
#container .uic-title-pattern .caption {
  margin-top: 1.2em;
}
